for (auto it = triangulation.finite_cells().begin(); it != triangulation.finite_cells().end(); ++it) {
    Tetrahedron tet;
    for (int i = 0; i < 4; ++i) {
        CGALPoint p = it->vertex(i)->point();
        tet[i] = Point3d(CGAL_NAMED_VALUE_attribute(p, x), CGAL_NAMED_VALUE_attribute(p, y), CGAL_NAMED_VALUE_attribute(p, z));
    }
    // Note: In CGAL, the point coordinates are accessed via CGAL::get() or simply by the point's members
    // Based on the context of Point3d and CGALPoint:
    tet[0] = Point3d(it->vertex(0)->point().x(), it->vertex(0)->point().y(), it->vertex(0)->point().z());
    tet[1] = Point3d(it->vertex(1)->point().x(), it->vertex(1)->point().y(), it->vertex(1)->point().z());
    tet[2] = Point3d(it->vertex(2)->point().x(), it->vertex(2)->point().y(), it->vertex(2)->point().z());
    tet[3] = Point3d(it->vertex(3)->point().x(), it->vertex(3)->point().y(), it->vertex(3)->point().z());
    tetrahedra.push_back(tet);
}
return tetrahedra;

